using Microsoft.Maui.Storage;

namespace CustomSoundboard.Models;

public enum SymbolPack
{
    Mulberry,
    OpenMoji,
}

/// <summary>
/// One packaged picture a tile can use. <paramref name="Asset"/> is the name a tile saves; <see cref="SymbolCatalog.ImageFor"/>
/// turns it into a picture.
/// </summary>
public sealed record Symbol(string Asset, string Label, SymbolPack Pack)
{
    public ImageSource Image => SymbolCatalog.ImageFor(Asset);
}

/// <summary>
/// The packaged symbols, from Resources/Packs/manifest.csv. Mulberry Symbols (Steve Lee) and OpenMoji are both
